CREATE TABLE course_modules (id UUID PRIMARY KEY, course_id UUID NOT NULL REFERENCES courses(id) ON DELETE CASCADE, title VARCHAR(180) NOT NULL, sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE lessons (id UUID PRIMARY KEY, module_id UUID NOT NULL REFERENCES course_modules(id) ON DELETE CASCADE, title VARCHAR(220) NOT NULL, content_type VARCHAR(30) NOT NULL DEFAULT 'TEXT', content VARCHAR(4000), sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE course_enrollments (id UUID PRIMARY KEY, course_id UUID NOT NULL REFERENCES courses(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, progress_percent INT NOT NULL DEFAULT 0 CHECK(progress_percent BETWEEN 0 AND 100), completed_at TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, version BIGINT NOT NULL DEFAULT 0, UNIQUE(course_id,user_id));
CREATE INDEX idx_modules_course ON course_modules(course_id); CREATE INDEX idx_lessons_module ON lessons(module_id); CREATE INDEX idx_enrollments_user ON course_enrollments(user_id);